session_start();require_once '../config/database.php';require_once 'lib.php';if(!isset($_SESSION['user_id'])){header('Location: ../login.php');exit;}$railroad=ttOperationsRailroad($pdo,(int)$_SESSION['user_id']);$id=(int)($_GET['id']??0);$stmt=$pdo->prepare('SELECT sl.*,a.title_snapshot,a.crew_name,a.operating_pattern,s.operating_date FROM operation_switch_lists sl JOIN operation_assignments a ON a.id=sl.assignment_id JOIN operating_sessions s ON s.id=sl.session_id WHERE sl.id=? AND sl.railroad_id=?');$stmt->execute([$id,(int)$railroad['id']]);$list=$stmt->fetch(PDO::FETCH_ASSOC);if(!$list){http_response_code(404);die('Work order not found.');}$pdo->prepare('UPDATE operation_switch_lists SET printed_at=NOW() WHERE id=? AND railroad_id=?')->execute([$id,(int)$railroad['id']]);$stmt=$pdo->prepare('SELECT * FROM operation_switch_list_moves WHERE switch_list_id=? ORDER BY sequence_number');$stmt->execute([$id]);$moves=$stmt->fetchAll(PDO::FETCH_ASSOC);
