<?php include '../includes/header.php';?><title>Print <?=ttHtml($list['switch_list_number'])?></title><link rel="stylesheet" href="../assets/css/operations.css"></head><body><div class="container-fluid py-3"><div class="d-flex justify-content-between"><div><h1><?=ttHtml($list['switch_list_number'])?> — Revision <?=(int)$list['revision_number']?></h1><p><?=ttHtml($list['title_snapshot'].' · '.$list['operating_date'].' · Crew: '.($list['crew_name']?:'Unassigned'))?></p></div><button class="btn btn-primary" onclick="window.print()">Print</button></div><table class="table table-bordered tt-work-order-table"><thead><tr><th>Done</th><th>Photo</th><th>Car</th><th>Action</th><th>Instruction</th><th>From</th><th>To</th><th>Actual / Exception</th></tr></thead><tbody><?php foreach($moves as $move):?><tr><td>☐</td><td><?php if($url=ttPhotoUrl($move['photo_filename_snapshot'])):?><img class="tt-car-thumb" src="<?=ttHtml($url)?>" alt="<?=ttHtml(trim($move['reporting_marks_snapshot'].' '.$move['road_number_snapshot']))?>"><?php endif;?></td><td><?=ttHtml(trim($move['reporting_marks_snapshot'].' '.$move['road_number_snapshot']))?></td><td><?=ttHtml($move['action'])?></td><td><?=ttHtml($move['instruction'])?></td><td><?=ttHtml(trim($move['origin_name_snapshot'].' / '.$move['origin_track'],' /'))?></td><td><?=ttHtml(trim($move['destination_name_snapshot'].' / '.$move['destination_track'],' /'))?></td><td style="min-width:180px"></td></tr><?php endforeach;?></tbody></table></div></body></html>
